                    # Find highest test accuracy and corresponding train accuracy
            max_test_acc = max(test_acc)
            max_index = test_acc.index(max_test_acc)
            max_train_acc = train_acc[max_index]
            
            # Draw a star marker at the highest test accuracy point
            ax.scatter(max_train_acc, max_test_acc, color=[plt.get_cmap('coolwarm')(num_samples[max_index] / max(num_samples))], marker='*', s=250, edgecolors='k', label='Highest Test Accuracy')
